d. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.","title":"Creative direction","variables":[{"defaultValue":"A neighborhood night market remembered from the late 1970s","id":"brief","label":"Creative brief","required":true,"type":"text"},{"defaultValue":"period-informed palette","id":"method","label":"Visual method","type":"string"},{"defaultValue":"materials, color limits, and layout evoke an era without copying a known work","id":"structure","label":"Composition rule","type":"string"}]},"schema":"prompt-canvas.prompt-workspace-template@2","source":{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Era palette editorial"},"status":"starter","tags":["editorial poster","retro palette poster","period color study"],"thumbnail":{"alt":"First-party graphic preview for Era palette editorial, illustrating period-informed palette.","assetPath":"/recipe-thumbnails/original-systems/era-palette-editorial.svg"},"title":"Era palette editorial","version":1,"x-agent-authoring":{"generationDefault":1,"origin":"independent-first-party","reviewState":"owner-requested-original-authoring"},"x-discovery":{"badges":["No photo needed","Makes 1 image"],"collection":"original-systems","complexity":"guided","inputModes":["text"],"inputSummary":["A creative brief"],"intentAliases":["retro palette poster","period color study","historical editorial mood"],"intents":["create"],"outputKinds":["image"],"preservationNeeds":[],"requiredInputSummary":["A short creative brief"],"subjectKinds":["person","object","place","concept"],"thumbnail":{"alt":"First-party graphic preview for Era palette editorial, illustrating period-informed palette.","src":"/recipe-thumbnails/original-systems/era-palette-editorial.svg"},"userPromise":"Translate a period mood into an original palette and print treatment without imitation."},"x-presentation":{"advancedControlIds":[],"initialView":"canvas","primaryControlIds":["brief","method","structure","aspect-ratio"],"resultEmphasis":"hero","showPromptByDefault":false}}', 'prompt-canvas.prompt-workspace-template@2', 'sha256:95c6b30689df8455f5298b544ea30d7961e9cdc70f315241e98637e59bbb1c7c', 'Translate a period mood into an original palette and print treatment without imitation. Create an original, polished image for this brief: {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.', NULL, '{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Era palette editorial"}', 'Initial official catalog publication.', '2026-09-03T00:00:00Z', '2026-09-03T00:00:00Z');
