nding":{"mode":"agent-context","target":"edit.subjectPlacement"},"defaultValue":"preserve","id":"subject-placement","label":"Subject placement","options":[{"label":"Preserve position","value":"preserve"},{"label":"Center","value":"center"},{"label":"Rule of thirds","value":"thirds"}],"type":"composition"}],"description":"Adapt an image to a new shape without awkward cropping.","generation":{"capability":"image-generation","defaultOperation":"edit","delivery":"webmcp-import","operations":["edit","upscale"],"preferredMimeTypes":["image/png","image/webp"],"provider":"codex"},"id":"expand-reframe","layout":{"arrangement":"reference-transform","mode":"seeded","preserveManualGeometry":true},"outputs":[{"count":1,"id":"primary","kind":"image","label":"Reframed image","layoutHint":"hero","operations":["edit","upscale"],"role":"primary"}],"preservation":[{"description":"Preserve the important subject region, perspective, scale, and lighting.","id":"protected-region","strength":"must"}],"prompt":{"body":"Adapt the supplied image to {{target_ratio}} using the selected framing method. Protect the important subject region, horizon, perspective, scale, and lighting. When extending, continue plausible scene geometry and texture. When cropping, keep the focal subject complete and the composition balanced.","title":"Expand or reframe","variables":[{"defaultValue":"16:9","id":"target_ratio","label":"Target aspect ratio","required":true,"type":"enum","values":["1:1","4:5","3:2","16:9"]}]},"references":[{"acceptedMimeTypes":["image/jpeg","image/png","image/webp"],"id":"source-photo","label":"Source image","multiple":false,"preserve":["important subject region","perspective","scale","lighting"],"required":true,"role":"source-photo"}],"schema":"prompt-canvas.prompt-workspace-template@2","source":{"creator":"Prompt Canvas","kind":"first-party","promptUsage":"original","title":"Expand or reframe an image"},"status":"starter","tags":["make wider","outpaint","crop","reframe","extend image"],